@Composable
fun TooSoonWarningDialog(
    minutesRemaining: Long,
    onConfirm: () -> Unit,
    onDismiss: () -> Unit,
) {
    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(stringResource(R.string.log_dose_anyway_title)) },
        text = {
            Text(stringResource(R.string.too_soon_warning_body, minutesRemaining))
        },
        confirmButton = {
            TextButton(onClick = onConfirm) { Text(stringResource(R.string.log_anyway)) }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text(stringResource(R.string.cancel)) }
        },
    )
}
